function createMedianFinder() {
  const makeHeap = (less) => {
    const h = []
    const swap = (a, b) => {
      ;[h[a], h[b]] = [h[b], h[a]]
    }
    return {
      size: () => h.length,
      peek: () => h[0],
      push(x) {
        h.push(x)
        let i = h.length - 1
        while (i > 0) {
          const p = Math.floor((i - 1) / 2)
          if (!less(h[i], h[p])) break
          swap(i, p)
          i = p
        }
      },
      pop() {
        const top = h[0]
        const last = h.pop()
        if (h.length > 0) {
          h[0] = last
          let i = 0
          while (true) {
            let s = i
            const l = 2 * i + 1
            const r = 2 * i + 2
            if (l < h.length && less(h[l], h[s])) s = l
            if (r < h.length && less(h[r], h[s])) s = r
            if (s === i) break
            swap(i, s)
            i = s
          }
        }
        return top
      },
    }
  }
  const low = makeHeap((a, b) => a > b)
  const high = makeHeap((a, b) => a < b)
  return {
    add(x) {
      low.push(x)
      high.push(low.pop())
      if (high.size() > low.size()) low.push(high.pop())
    },
    median() {
      if (low.size() === 0) return undefined
      if (low.size() > high.size()) return low.peek()
      return (low.peek() + high.peek()) / 2
    },
  }
}

