function maxMeetings(intervals) {
  const sorted = [...intervals].sort((a, b) => a[1] - b[1])
  let lastEnd = -Infinity
  let count = 0
  for (const [s, e] of sorted) {
    if (s >= lastEnd) {
      count++
      lastEnd = e
    }
  }
  return count
}

