function shortestPath(n, edges, start, end) {
  const adj = Array.from({ length: n }, () => [])
  for (const [a, b] of edges) {
    adj[a].push(b)
    adj[b].push(a)
  }
  const dist = new Array(n).fill(-1)
  dist[start] = 0
  let queue = [start]
  while (queue.length) {
    const next = []
    for (const u of queue) {
      for (const v of adj[u]) {
        if (dist[v] === -1) {
          dist[v] = dist[u] + 1
          next.push(v)
        }
      }
    }
    queue = next
  }
  return dist[end]
}

